// Ukázkový lead ve tvaru, v jakém ho vrací trigger Facebook Lead Ads. Smyšlené údaje, žádná reálná osoba.
const stamp = Date.now();
return [{ json: {
  id: 'TEST-' + stamp,
  created_time: new Date().toISOString(),
  form_id: '000000000000001',
  form_name: 'TEST formulář',
  campaign_id: '000000000000002',
  campaign_name: 'TEST kampaň',
  ad_id: '000000000000003',
  field_data: [
    { name: 'full_name', values: ['Test Testovič'] },
    { name: 'email', values: ['test@example.test'] },
    { name: 'phone_number', values: ['+420 777 000 000'] },
    { name: 'company_name', values: ['Test s.r.o.'] },
  ],
} }];

// Převede lead z Meta na tělo, které OPSYS přijímá (viz packages/modules/reklama/src/contract.ts#leadIngestPayload).
// Povinné: leadgenId a formId. Údaje o člověku posílá fieldData tak, jak je dodala Meta (OPSYS si pole rozpozná podle názvu).
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const leadgenId = String(j.leadgen_id || j.leadgenId || j.id || '').trim();
  const formId = String(j.form_id || j.formId || '').trim();
  if (!leadgenId || !formId) throw new Error('Lead nemá leadgenId nebo formId, nelze ho předat OPSYS.');
  const fieldData = (j.field_data || j.fieldData || [])
    .filter((f) => f && f.name)
    .map((f) => ({ name: String(f.name), values: Array.isArray(f.values) ? f.values.map((v) => String(v)) : [String(f.values == null ? '' : f.values)] }));
  const body = { leadgenId, formId, fieldData };
  const put = (key, value) => { if (value !== undefined && value !== null && String(value).trim() !== '') body[key] = String(value).trim(); };
  put('formName', j.form_name || j.formName);
  put('pageId', j.page_id || j.pageId);
  put('createdTime', j.created_time || j.createdTime);
  put('campaignId', j.campaign_id || j.campaignId);
  put('campaignName', j.campaign_name || j.campaignName);
  put('adsetId', j.adset_id || j.adsetId);
  put('adsetName', j.adset_name || j.adsetName);
  put('adId', j.ad_id || j.adId);
  put('adName', j.ad_name || j.adName);
  out.push({ json: { body } });
}
return out;

// Podpis příchozího požadavku: X-Opsys-Signature = t=<unix>,v1=<hex HMAC-SHA256(tajemství, t + "." + tělo)>.
// Tělo se serializuje jednou a HTTP uzel níže ho posílá přesně tak. Vyžaduje NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
let env = {};
try { env = $env; } catch (e) { env = {}; }
const secret = env.OPSYS_INGEST_SECRET || '<<DOPLNIT: tajemství příchozích požadavků>>';
const base = String(env.OPSYS_BASE_URL || '<<DOPLNIT: adresa OPSYS>>').replace(/\/+$/, '');
if (secret.includes('DOPLNIT') || base.includes('DOPLNIT')) throw new Error('Workflow není nastavené: chybí OPSYS_INGEST_SECRET nebo OPSYS_BASE_URL.');
return $input.all().map((item) => {
  const body = JSON.stringify(item.json.body);
  const t = Math.floor(Date.now() / 1000);
  const sig = crypto.createHmac('sha256', secret).update(t + '.' + body).digest('hex');
  return { json: { url: base + '/api/ingest/leads', body, signature: 't=' + t + ',v1=' + sig } };
});
